csharp\nusing UnityEngine;\nusing AirHockey.Core.Physics;\n\nnamespace AirHockey.AI\n{\n public class AIAgent : MonoBehaviour\n {\n [SerializeField] private AIDifficultyProfile profile;\n [SerializeField] private MalletController mallet;\n [SerializeField] private Transform ownHalf;\n\n private PuckController puck;\n private float timer;\n private void Start() => puck = FindObjectOfType<PuckController>();\n\n private void Update()\n {\n if (!puck) return;\n\n timer += Time.deltaTime;\n if (timer < profile.ReactionTime) return;\n timer = 0f;\n\n Vector2 target = puck.transform.position +\n (Vector3)(puck.GetComponent<Rigidbody2D>().velocity * profile.PredictionLag);\n\n target.y = Mathf.Clamp(target.y, ownHalf.position.y - 4f, ownHalf.position.y + 4f);\n\n mallet.transform.position = Vector2.MoveTowards(\n mallet.transform.position,\n target,\n profile.MoveSpeed * Time.deltaTime);\n }\n }\n}\n